// src/lib/report.js
//
// Hard rule (per product spec): the report must clearly separate
//  1) Observed Results   - raw counts/percentages straight from the data
//  2) Calculated Statistics - derived numbers (rates, averages)
//  3) Platform Recommendations - explicitly labeled, never blended into 1/2
// Nothing here is generated by a language model; every number is computed
// directly from `answers` rows. This works with zero AI-API dependency,
// exactly as required for P0.

import { db } from '../db.js';

export function generateReport(researchProjectId) {
  const project = db.prepare('SELECT * FROM research_projects WHERE id = ?').get(researchProjectId);
  if (!project) throw new Error('Research project not found');

  const allResponses = db.prepare('SELECT * FROM survey_responses WHERE research_project_id = ?').all(researchProjectId);
  const validResponses = allResponses.filter(r => r.status === 'VALID');
  const questions = db.prepare('SELECT * FROM survey_questions WHERE research_project_id = ? ORDER BY order_index').all(researchProjectId);

  const totalResponses = allResponses.length;
  const validCount = validResponses.length;
  const completedCount = allResponses.filter(r => r.completed_at).length;
  const completionRate = totalResponses > 0 ? Math.round((completedCount / totalResponses) * 1000) / 10 : 0;
  const validRate = totalResponses > 0 ? Math.round((validCount / totalResponses) * 1000) / 10 : 0;

  const validResponseIds = validResponses.map(r => r.id);
  const questionAnalytics = questions.map(q => {
    const answers = validResponseIds.length
      ? db.prepare(`SELECT * FROM answers WHERE question_id = ? AND response_id IN (${validResponseIds.map(() => '?').join(',')})`).all(q.id, ...validResponseIds)
      : [];

    const base = { questionId: q.id, questionText: q.question_text, questionType: q.question_type, responseCount: answers.length };

    if (q.question_type === 'single_choice' || q.question_type === 'yes_no') {
      const options = db.prepare('SELECT * FROM question_options WHERE question_id = ? ORDER BY order_index').all(q.id);
      const counts = {};
      for (const a of answers) {
        const ids = JSON.parse(a.selected_option_ids || '[]');
        for (const id of ids) counts[id] = (counts[id] || 0) + 1;
      }
      const breakdown = options.map(o => ({
        option: o.option_text,
        count: counts[o.id] || 0,
        percent: answers.length ? Math.round(((counts[o.id] || 0) / answers.length) * 1000) / 10 : 0,
      }));
      return { ...base, breakdown };
    }

    if (q.question_type === 'multi_choice') {
      const options = db.prepare('SELECT * FROM question_options WHERE question_id = ? ORDER BY order_index').all(q.id);
      const counts = {};
      for (const a of answers) {
        const ids = JSON.parse(a.selected_option_ids || '[]');
        for (const id of ids) counts[id] = (counts[id] || 0) + 1;
      }
      const breakdown = options.map(o => ({
        option: o.option_text,
        count: counts[o.id] || 0,
        percentOfRespondents: answers.length ? Math.round(((counts[o.id] || 0) / answers.length) * 1000) / 10 : 0,
      }));
      return { ...base, breakdown };
    }

    if (q.question_type === 'rating_5' || q.question_type === 'rating_10') {
      const values = answers.map(a => a.rating_value).filter(v => v !== null && v !== undefined);
      const avg = values.length ? Math.round((values.reduce((s, v) => s + v, 0) / values.length) * 100) / 100 : null;
      return { ...base, average: avg, distribution: values };
    }

    // short_text / long_text: simple keyword frequency clustering (no NLP/LLM dependency)
    const texts = answers.map(a => (a.text_answer || '').toLowerCase());
    const wordFreq = {};
    const stopwords = new Set(['the','a','an','and','or','is','it','to','of','for','in','on','with','i','my','we']);
    for (const t of texts) {
      for (const w of t.split(/\W+/)) {
        if (w.length < 3 || stopwords.has(w)) continue;
        wordFreq[w] = (wordFreq[w] || 0) + 1;
      }
    }
    const topThemes = Object.entries(wordFreq).sort((a, b) => b[1] - a[1]).slice(0, 8).map(([word, count]) => ({ word, count }));
    return { ...base, sampleAnswers: texts.slice(0, 5), topThemes };
  });

  // A very small, transparent recommendation rule: not AI-generated, just a
  // plain-language readout of the top single/yes_no choice question, clearly
  // separated from the "observed" numbers above it.
  const recommendations = [];
  if (validCount < 30) {
    recommendations.push(`Sample size (${validCount} valid responses) is small — treat findings as directional, not conclusive. Consider running a larger study before making a final decision.`);
  }
  const primaryChoice = questionAnalytics.find(q => q.breakdown && q.breakdown.length);
  if (primaryChoice) {
    const top = [...primaryChoice.breakdown].sort((a, b) => b.count - a.count)[0];
    if (top && top.percent !== undefined) {
      recommendations.push(`On "${primaryChoice.questionText}", the leading response was "${top.option}" at ${top.percent}% of respondents — consider this the strongest signal from this study.`);
    }
  }

  return {
    project: { id: project.id, title: project.title, status: project.status, target_city: project.target_city },
    observedResults: {
      totalResponses,
      validResponses: validCount,
      flaggedOrRejected: totalResponses - validCount,
    },
    calculatedStatistics: {
      completionRatePercent: completionRate,
      validResponseRatePercent: validRate,
    },
    questionAnalytics,
    platformRecommendations: recommendations,
    generatedAt: new Date().toISOString(),
  };
}
